<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>PHP Images - Level 5 and 6</title>

    <style>
        /* How to slideshow CSS */
        /* Sets the box sizing for the slideshow */
        * {
            box-sizing: border-box;
        }

        /* Creates the main slideshow container. */
        .slideshow-container {
            max-width: 800px;
            position: relative;
            margin: auto;
        }

        /* How to slideshow */
        /* Displays the selected slide generated by PHP */
        .mySlides {
            display: block;
        }

        /* Styling for the image inside the slid */
        .mySlides img {
            width: 100%;
        }

        /* Styling for the previous and next arrows */
        .prev, .next {
            cursor: pointer;
            position: absolute;
            top: 50%;
            width: auto;
            margin-top: -22px;
            padding: 16px;
            color: white;
            font-weight: bold;
            font-size: 18px;
            transition: 0.6s ease;
            border-radius: 0 3px 3px 0;
            user-select: none;
            text-decoration: none;
        }

        /* Positions the next arrow on the right */
        .next {
            right: 0;
            border-radius: 3px 0 0 3px;
        }

        /* Changes arrow backgrounds when hovered over */
        .prev:hover, .next:hover {
            background-color: rgba(0,0,0,0.8);
        }

        /* Styling for the image caption */
        .text {
            color: white;
            font-size: 15px;
            padding: 8px 12px;
            position: absolute;
            bottom: 28px;
            width: 100%;
            text-align: center;
            background-color: rgba(0,0,0,0.5);
        }

        /* Styling for the slide numbers */
        .numbertext {
            color: white;
            font-size: 12px;
            padding: 8px 12px;
            position: absolute;
            top: 0;
        }

        /* Styling for navigation dots */
        .dot {
            cursor: pointer;
            height: 15px;
            width: 15px;
            margin: 0 2px;
            background-color: #bbb;
            border-radius: 50%;
            display: inline-block;
            transition: background-color 0.6s ease;
        }

        /* CSS Text Alignment */
        /* Centers the navigation dots below the image */
        .dots-container {
            text-align: center;
        }

        /* Highlights the active dot */
        .active, .dot:hover {
            background-color: #717171;
        }
    </style>

</head>

<body>

<h1>PHP Image Slideshow</h1>

<!-- How to slideshow HTML -->
<!-- Creates the main container for the slideshow -->
<div class="slideshow-container">

    <!-- PHP Include Files -->
    <!-- Includes the file with the PHP that creates and controls the slideshow -->
    <?php include 'slideshow.php'; ?>

</div>

</body>
</html>